# link.map —— 落点声明（唯一一份）
#
# 这个仓库里「什么文件链到哪里」只在这里声明一次。
# 安装脚本读它，macview 也读它。**不要在别处再写第二份。**
#
# 格式：<仓库内相对路径>  <$HOME 内相对路径>  [平台]
#
#   - 平台留空 = 所有平台；写 macos / linux 则只在那个平台链接
#   - 源按 src/{平台}/config/ → src/common/config/ 的顺序查找
#     （即平台目录覆盖通用目录，找不到平台的再退到通用）
#   - `#` 之后是注释，空行忽略
#   - 路径必须相对 $HOME，脚本会拒绝绝对路径和 $HOME 本身
#
# 加一条：在这里加一行，然后确认 src/ 下真的有对应的源。

zsh/zshenv              .zshenv
zsh/zprofile            .zprofile
zsh/zshrc               .zshrc
aliases                 .aliases
zsh/oh-my-zsh.sh        .oh-my-zsh.sh
zsh/os.zsh              .config/dotfiles/os.zsh
zsh/ohmyzsh.plugins.zsh .config/dotfiles/ohmyzsh.plugins.zsh
tmux/tmux.conf          .tmux.conf
tmux/config             .config/tmux
nvim                    .config/nvim
git/gitconfig           .gitconfig
mise/config.toml        .config/mise/config.toml
env/envconfig           .envconfig
shell/bash_profile      .bash_profile
ghostty                 .config/ghostty          macos
